test('charging situation is one retained Hero heading and known model metadata remains a figure caption through image failure',()=>{
 const {root}=fixture(),view=new VehicleView(root),model=vehicleFixture({charging:true}),refs=[view.hero,view.status,view.figure,view.image,view.context,...view.metrics.children];view.render(model);assert.equal(view.title.textContent,'Tesla');assert.equal(view.status.tagName,'H2');assert.equal(view.status.dataset.kitSlot,'title');assert.equal(view.status.textContent,'Bilen lader');assert.equal(model.status,'Lader');assert.equal(view.model.status,'Lader');assert.equal(view.context.tagName,'FIGCAPTION');assert.equal(view.context.parentNode,view.figure);assert.deepEqual(view.figure.children,[view.image,view.context]);assert.equal(view.context.textContent,'Model Y · 2023');assert.equal(view.context.hidden,false);assert.equal(view.hero.children.includes(view.context),false);assert.equal(descendants(view.hero).filter(node=>node.dataset.kitSlot==='title').length,1);
 const descriptor=Object.getOwnPropertyDescriptor(Node.prototype,'textContent');let writes=0;for(const node of [view.status,view.context])Object.defineProperty(node,'textContent',{get(){return descriptor.get.call(this);},set(value){writes++;descriptor.set.call(this,value);}});view.render(model);assert.equal(writes,0,'an identical observation does not rewrite retained heading or caption');assert.deepEqual([view.hero,view.status,view.figure,view.image,view.context,...view.metrics.children],refs);
 view.image.dispatchEvent(new Event('error'));assert.equal(view.image.hidden,true);assert.equal(view.figure.hidden,false);assert.equal(view.context.hidden,false);assert.equal(view.context.parentNode,view.figure);assert.equal(view.context.textContent,'Model Y · 2023');assert.equal(view.heroIcon.hidden,false);assert.equal(view.status.textContent,'Bilen lader');assert.equal(view.batteryValue.textContent,'72 %');assert.equal(view.rangeValue.textContent,'312 km');view.image.dispatchEvent(new Event('load'));assert.equal(view.image.hidden,false);assert.equal(view.context.parentNode,view.figure);view.cleanup();
});

