test('preview controls commit bounded values, require lock confirmation and clean up listeners',async()=>{const {vehiclePreviewAction}=await import('../../podvoice/gatekeeper/static/podview/vehicle-model.js');const {root}=fixture();let state=vehicleFixture({controls:true});const view=new VehicleView(root,{onAction:event=>{state=vehiclePreviewAction(state,event);view.render(state);}});view.render(state);assert.equal(view.climateToggle.dataset.kitVariant,'power');view.climateToggle.dispatchEvent(new Event('click'));assert.equal(state.climate.status,'off');view.lockConfirm.dispatchEvent(new Event('click'));assert.equal(state.climate.status,'heat');assert.equal(view.climateToggle.dataset.kitVariant,'power');view.temperatureUp.dispatchEvent(new Event('click'));assert.equal(view.confirmation.open,false);assert.equal(state.climate.targetTemperatureC,22);view.lockButton.dispatchEvent(new Event('click'));assert.equal(state.locked,true);assert.equal(view.lockConfirm.hidden,false);view.lockConfirm.dispatchEvent(new Event('click'));assert.equal(state.locked,false);assert.equal(view.lockButton.dataset.kitVariant,'secondary');assert.equal(view.lockButton.dataset.tone,'neutral');assert.equal(descendants(root).filter(node=>node.tagName==='INPUT').length,8);for(const event of [{action:'charge-limit',value:101},{action:'temperature',value:15},{action:'lock'},{action:'climate',revision:0}])assert.equal(vehiclePreviewAction(state,{revision:state.revision,...event}),state);view.render(state,{connected:false});assert.equal(view.climateToggle.disabled,true);const before=state;view.climateToggle.dispatchEvent(new Event('click'));assert.equal(state,before);view.cleanup();view.render(state);view.temperatureUp.dispatchEvent(new Event('click'));assert.equal(state,before);});


