test('confirmed local lock controls keep Hero and Access consistent without replacing charging status',async()=>{
 const {vehiclePreviewAction}=await import('../../podvoice/gatekeeper/static/podview/vehicle-model.js');
 for(const charging of [false,true]){
  const {root}=fixture();let state=vehicleFixture({charging,controls:true});const view=new VehicleView(root,{onAction:event=>{state=vehiclePreviewAction(state,event);view.render(state);}});view.render(state);
  const hero=view.hero,status=view.status;
  for(const locked of [false,true]){
   const previous=state,revision=state.revision;view.lockButton.dispatchEvent(new Event('click'));if(!locked){assert.strictEqual(state,previous);assert.equal(view.confirmation.open,true);view.lockConfirm.dispatchEvent(new Event('click'));}else assert.equal(view.confirmation.open,false);assert.equal(state.locked,locked);assert.equal(state.revision,revision+1);assert.equal(state.status,charging?'Lader':`${locked?'Låst':'Ulåst'}`);assert.equal(view.status.textContent,charging?'Bilen lader':state.status);assert.equal(view.access.status.textContent,locked?'Låst':'Ulåst');assert.equal(view.lockButton.textContent,locked?'Lås op':'Lås bilen');assert.equal(view.hero,hero);assert.equal(view.status,status);
   const current=state;view.lockConfirm.dispatchEvent(new Event('click'));assert.strictEqual(state,current,'a completed confirmation cannot be replayed');
  }
  view.cleanup();
 }
});

