test('charge source events require a new eligible observation within the same current read scope',()=>{
 const sample=(observedAt,batteryPercent=71,status='charging')=>vehicleObservation({status:'observed',source:'home_assistant_state',observedAt,entityIds:['sensor.car_charge'],data:{batteryPercent,charging:{status},climate:{}}}),context={connected:true,readGranted:true,scope:'current',sourceScope:'current'},first=vehicleChargeUpdate(null,sample(100),context);
 assert.equal(first.cue,false);assert.equal(vehicleChargeUpdate(first,sample(101,72),context).cue,true);assert.equal(vehicleChargeUpdate(first,sample(101,71),context).cue,false);assert.equal(vehicleChargeUpdate(first,sample(100,72),context).cue,false);assert.equal(vehicleChargeUpdate(first,sample(99,72),context).cue,false);
 for(const next of [null,vehicleFixture({charging:true}),{...sample(101,72),stale:true},sample(101,null),sample(101,72,'stopped')])assert.equal(vehicleChargeUpdate(first,next,context).cue,false);
 for(const patch of [{connected:false},{readGranted:false},{sourceScope:'foreign'},{scope:'other',sourceScope:'other'},{visible:false},{suppress:true}])assert.equal(vehicleChargeUpdate(first,sample(101,72),{...context,...patch}).cue,false);
 let replay;const cues=[];for(const [at,percent]of [[100,71],[101,72],[100,71],[101,72],[102,72]]){replay=vehicleChargeUpdate(replay,sample(at,percent),context);cues.push(replay.cue);}assert.deepEqual(cues,[false,true,false,false,false],'an older reading cannot rewind the acknowledged timestamp or percentage baseline');assert.equal(replay.observedAt,102);assert.equal(replay.percent,72);
 const stopped=vehicleChargeUpdate(null,sample(100,0,'stopped'),context);assert.equal(vehicleChargeUpdate(stopped,sample(101,0),context).cue,true,'zero is an actual known reading, and entering charging is an actual event');
 const stale=vehicleChargeUpdate(first,{...sample(101,72),stale:true},context);assert.equal(vehicleChargeUpdate(stale,sample(102,73),context).cue,false,'first fresh recovery is a static baseline');
});

test('actual VehicleView uses finite shared leaf motion only after updating a fresh charging reading',async()=>{
 const {root}=fixture(),host={dataset:{},isConnected:true},view=new VehicleView(root),calls=[],events=[],context={connected:true,readGranted:true,scope:'current',sourceScope:'current'};host.motion=new SceneMotion(host);root.closest=()=>host;const meter=view.meter;meter.getClientRects=()=>[{}];
 meter.animate=(frames,options)=>{let resolve;const animation={finished:new Promise(done=>{resolve=done;}),cancelled:false,cancel(){this.cancelled=true;resolve();},finish(){resolve();}};calls.push({frames,options,animation,value:meter.value});return animation;};
 const sample=(at,percent=71,status='charging')=>vehicleObservation({status:'observed',source:'home_assistant_state',observedAt:at,entityIds:['sensor.car_charge'],data:{batteryPercent:percent,charging:{status,powerKw:11},climate:{}}});
 view.onAction=e=>events.push(e);view.render(sample(100),{connected:false,chargeContext:context});assert.equal(calls.length,0);view.render(sample(101,72),{connected:false,chargeContext:context});assert.equal(calls.length,1);assert.equal(calls[0].value,72,'real native meter is updated before feedback');assert.deepEqual(calls[0].frames,[{opacity:.65},{opacity:1}]);assert.equal(calls[0].options.duration,120);assert.equal(calls[0].options.iterations,undefined);assert.equal(view.meter,meter);assert.deepEqual(view.model.actions,[]);assert.equal(view.controlsEnabled,false);
 view.render(sample(101,72),{chargeContext:context});view.render(sample(102,72),{chargeContext:context});assert.equal(calls.length,1);assert.equal(calls[0].animation.cancelled,false,'unchanged data does not restart or interrupt actual feedback');calls[0].animation.finish();await Promise.resolve();await Promise.resolve();await Promise.resolve();assert.equal(host.motion.animations.size,0);
 view.render(sample(103,73),{chargeContext:context});assert.equal(calls.length,2);view.render({...sample(104,74),stale:true},{chargeContext:context});assert.equal(calls[1].animation.cancelled,true);assert.equal(view.meter.value,74);view.render(sample(105,75),{chargeContext:context});assert.equal(calls.length,2,'fresh recovery is silent');
 host.dataset.motion='reduced';view.render(sample(106,76),{chargeContext:context});assert.equal(calls.length,2);assert.equal(view.meter.value,76);host.dataset.motion='normal';view.render(sample(106,76),{chargeContext:context});assert.equal(calls.length,2,'motion preference change does not replay source events');view.render(sample(107,77),{chargeContext:{...context,suppress:true}});assert.equal(calls.length,2,'navigation seeds current data without replay');view.render(sample(108,78),{chargeContext:context});assert.equal(calls.length,3);view.cleanup();assert.equal(calls[2].animation.cancelled,true);assert.equal(view.chargePresentation,null);assert.deepEqual(events,[]);host.motion.cancel();
});


